gsap.from(".brand-art h1",{duration:1.5,y:50,opacity:0,ease:"power3.out",delay:.3});gsap.from(".tagline",{duration:1,y:30,opacity:0,ease:"power2.out",delay:.8});gsap.from(".heritage-badge",{duration:1,y:30,opacity:0,ease:"power2.out",delay:1.2});gsap.utils.toArray("section").forEach(e=>{ScrollTrigger.create({trigger:e,start:"top 70%",onEnter:()=>e.classList.add("animated"),once:!0})});
